import React from 'react';
import {AbsoluteFill, Easing, interpolate} from 'remotion';
import {useS, en, clamp, DUR, words} from './kit';

const W = 1080;
const H = 1920;

// Momentos clave
const EMPEZAR = en('empezar');
const VACIAS = en('vacías');
const SEÑOR = en('Señor');
const TIEMPO = en('tiempo');
const CUESTA = en('cuesta');
const LEVANTARSE = en('levantarse');
const AMANECER = en('amanecer');
const RENUEVAS = en('renuevas');
const MISERICORDIA = en('misericordia');
const TEMOR = en('temor');
const ESPERANZA = en('esperanza');
const ATRAS = en('atrás');
const CAMINOS = en('caminos');
const AMEN = en('amén');

const C_NOCHE = ['#0a0f24', '#1a1d36', '#2a2c48'];
const C_ALBA = ['#1e3c72', '#2a5298', '#ff9a9e'];
const C_DIA = ['#72afd3', '#37ecba', '#fff1eb'];

const mezcla = (a: string, b: string, k: number) => {
  const parse = (c: string) => c.replace('#', '').match(/.{2}/g)!.map((x) => parseInt(x, 16));
  const c1 = parse(a);
  const c2 = parse(b);
  const res = c1.map((v, i) => Math.round(v + (c2[i] - v) * k));
  return `rgb(${res[0]}, ${res[1]}, ${res[2]})`;
};

const Paisaje: React.FC<{progreso: number; s: number}> = ({progreso, s}) => {
  const g1 = mezcla('#1a1d36', '#4facfe', progreso);
  const g2 = mezcla('#0f1123', '#00f2fe', progreso);

  return (
    <AbsoluteFill>
      {/* Cielo */}
      <div style={{position: 'absolute', inset: 0, background: `linear-gradient(180deg, ${g1} 0%, ${g2} 100%)`}} />

      {/* Sol */}
      <div style={{
        position: 'absolute', 
        left: W / 2, 
        top: interpolate(progreso, [0, 1], [H + 200, 800], clamp),
        transform: 'translate(-50%, -50%)',
        width: 300, 
        height: 300, 
        borderRadius: '50%', 
        background: 'radial-gradient(circle, #fffbe8 0%, #ffd98a 60%, transparent 100%)',
        boxShadow: '0 0 100px #ffd98a',
        opacity: progreso
      }} />

      {/* Montañas fondo */}
      <svg width={W + 200} height={800} style={{position: 'absolute', bottom: 400, left: -100}} viewBox="0 0 1280 800">
        <path d="M0 800 L300 400 L600 600 L900 300 L1280 800 Z" fill={mezcla('#050714', '#2c3e50', progreso)} opacity={0.8} />
      </svg>

      {/* Colinas frente */}
      <svg width={W + 200} height={600} style={{position: 'absolute', bottom: 0, left: -100}} viewBox="0 0 1280 600">
        <path d="M0 600 Q 300 200 640 400 T 1280 300 L 1280 600 L 0 600 Z" fill={mezcla('#020308', '#134e5e', progreso)} />
      </svg>
    </AbsoluteFill>
  );
};

const Muñequito: React.FC<{s: number}> = ({s}) => {
  const levantado = interpolate(s, [LEVANTARSE, LEVANTARSE + 2], [0, 1], clamp);
  const vacias = interpolate(s, [VACIAS, VACIAS + 1], [0, 1], clamp);
  const respira = Math.sin(s * 1.5) * 5;

  return (
    <div style={{
      position: 'absolute', 
      left: W / 2 - 100, 
      top: 1350 - levantado * 50 + respira,
      width: 200, 
      height: 350
    }}>
      {/* Cuerpo */}
      <div style={{
        position: 'absolute',
        bottom: 0,
        left: 50,
        width: 100,
        height: 220,
        background: 'linear-gradient(180deg, #1a1c31, #0a0b1a)',
        borderRadius: '50px 50px 20px 20px',
        boxShadow: '0 10px 30px rgba(0,0,0,0.5)'
      }} />
      {/* Cabeza */}
      <div style={{
        position: 'absolute',
        top: 40,
        left: 65,
        width: 70,
        height: 75,
        background: 'radial-gradient(circle at 30% 30%, #2a2c48, #0a0b1a)',
        borderRadius: '50%'
      }} />
      {/* Brazos - Manos Vacías */}
      <div style={{
        position: 'absolute',
        left: 20,
        top: 130,
        width: 40,
        height: 12,
        background: '#1a1c31',
        borderRadius: 10,
        transform: `rotate(${interpolate(vacias, [0, 1], [70, -20], clamp)}deg)`,
        transformOrigin: 'right center',
        opacity: interpolate(s, [EMPEZAR, EMPEZAR + 0.5], [0, 1], clamp)
      }} />
      <div style={{
        position: 'absolute',
        right: 20,
        top: 130,
        width: 40,
        height: 12,
        background: '#1a1c31',
        borderRadius: 10,
        transform: `rotate(${interpolate(vacias, [0, 1], [-70, 20], clamp)}deg)`,
        transformOrigin: 'left center',
        opacity: interpolate(s, [EMPEZAR, EMPEZAR + 0.5], [0, 1], clamp)
      }} />
    </div>
  );
};

const Camino: React.FC<{s: number}> = ({s}) => {
  const progreso = interpolate(s, [CAMINOS, CAMINOS + 2], [0, 1], clamp);
  return (
    <svg width={W} height={600} style={{position: 'absolute', bottom: 0, left: 0, opacity: progreso}}>
      <defs>
        <linearGradient id="gradCamino" x1="0%" y1="100%" x2="0%" y2="0%">
          <stop offset="0%" stopColor="rgba(255,214,150,0.8)" />
          <stop offset="100%" stopColor="rgba(255,255,255,0)" />
        </linearGradient>
      </defs>
      <path d="M450 600 L540 100 L630 600 Z" fill="url(#gradCamino)" />
    </svg>
  );
};

const Particulas: React.FC<{s: number; t0: number}> = ({s, t0}) => {
  const visible = interpolate(s, [t0, t0 + 1], [0, 1], clamp);
  return (
    <AbsoluteFill style={{opacity: visible}}>
      {Array.from({length: 40}).map((_, i) => {
        const x = (i * 137) % W;
        const y = H - ((i * 263 + s * 100) % (H + 200));
        return (
          <div key={i} style={{
            position: 'absolute',
            left: x,
            top: y,
            width: 4 + (i % 4),
            height: 4 + (i % 4),
            borderRadius: '50%',
            background: '#fffbe8',
            boxShadow: '0 0 10px #fff',
            opacity: 0.4
          }} />
        );
      })}
    </AbsoluteFill>
  );
};

export const Escena: React.FC = () => {
  const {s} = useS();

  const luzAlba = interpolate(s, [AMANECER - 1, AMANECER + 4], [0, 1], clamp);
  const zoom = interpolate(s, [0, DUR], [1, 1.1], clamp);
  const subida = interpolate(s, [LEVANTARSE, LEVANTARSE + 5], [0, 100], clamp);

  return (
    <AbsoluteFill style={{backgroundColor: '#05070a', overflow: 'hidden'}}>
      <div style={{
        width: '100%', 
        height: '100%', 
        transform: `scale(${zoom}) translateY(${subida * -0.2}px)`,
        transformOrigin: 'bottom center'
      }}>

        <Paisaje progreso={luzAlba} s={s} />

        <Camino s={s} />

        <Muñequito s={s} />

        <Particulas s={s} t0={RENUEVAS} />

        {/* Rayos de luz en "esperanza" */}
        <AbsoluteFill style={{
          background: 'radial-gradient(circle at 50% 40%, rgba(255,255,255,0.2) 0%, transparent 70%)',
          opacity: interpolate(s, [ESPERANZA, ESPERANZA + 1, AMEN], [0, 1, 0.5], clamp),
          mixBlendMode: 'overlay'
        }} />

        {/* Brillo de manos en "pongo en tus manos" */}
        <div style={{
          position: 'absolute',
          left: W / 2,
          top: 1450,
          width: 200,
          height: 100,
          transform: 'translateX(-50%)',
          background: 'radial-gradient(ellipse, rgba(255,214,150,0.4) 0%, transparent 70%)',
          opacity: interpolate(s, [SEÑOR, SEÑOR + 1], [0, 1], clamp)
        }} />

      </div>

      {/* Viñeta final suave */}
      <AbsoluteFill style={{
        background: 'radial-gradient(circle, transparent 50%, rgba(0,0,0,0.4) 100%)',
        pointerEvents: 'none'
      }} />

      {/* Flash de misericordia */}
      <AbsoluteFill style={{
        background: '#fff',
        opacity: interpolate(s, [MISERICORDIA, MISERICORDIA + 0.1, MISERICORDIA + 0.5], [0, 0.15, 0], clamp)
      }} />
    </AbsoluteFill>
  );
};
